//! Keyfiles: a second factor stored as a file (e.g. on a USB stick).

use std::path::Path;

use zeroize::Zeroizing;

use crate::error::{Error, Result};
use crate::{fs_util, rng};

/// Size of keyfiles generated by Argus.
pub const GENERATED_LEN: usize = 64;
/// Any file up to this size may be used as a keyfile.
pub const MAX_KEYFILE_LEN: usize = 16 * 1024 * 1024;
/// Suggested extension.
pub const EXTENSION: &str = "argkey";

/// Write a new random keyfile. Fails if `path` already exists, so an
/// existing keyfile can never be overwritten by accident.
///
/// # Errors
/// I/O or RNG errors.
pub fn generate(path: &Path) -> Result<()> {
    let mut bytes = Zeroizing::new([0u8; GENERATED_LEN]);
    rng::fill(bytes.as_mut_slice())?;
    fs_util::write_new(path, bytes.as_slice())
}

/// Read a keyfile.
///
/// # Errors
/// I/O errors, [`Error::LimitExceeded`] if larger than 16 MiB,
/// [`Error::InvalidInput`] if empty.
pub fn read(path: &Path) -> Result<Zeroizing<Vec<u8>>> {
    let data = fs_util::read_limited(path, MAX_KEYFILE_LEN)?;
    if data.is_empty() {
        return Err(Error::InvalidInput("keyfile is empty"));
    }
    Ok(data)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::fs_util::test_util::TempDir;

    #[test]
    fn generate_and_read() {
        let dir = TempDir::new();
        let p = dir.0.join("k.argkey");
        generate(&p).unwrap();
        assert_eq!(read(&p).unwrap().len(), GENERATED_LEN);
        assert!(generate(&p).is_err(), "must not overwrite");
    }

    #[test]
    fn empty_keyfile_rejected() {
        let dir = TempDir::new();
        let p = dir.0.join("empty");
        std::fs::write(&p, b"").unwrap();
        assert!(read(&p).is_err());
    }
}
